/// <summary>
/// 126687 2nd API to communicate during submission / validation / posting of the journal
/// </summary>
class MET_CheckJournalPostStatusService
{
}

Method.Source:
    public MET_CheckJournalPostStatusResponse create(MET_CheckJournalPostStatusRequest _request)
    {
        JournalId               journalNum;
        LedgerJournalTable      lJournalTable;
        var response = new MET_CheckJournalPostStatusResponse();
        try
        {
            journalNum = _request.parmJournalId();

            changecompany(_request.parmDataAreaId())
            {
                select Posted, WorkflowApprovalStatus,METErrorLog from lJournalTable
                    where lJournalTable.JournalNum == journalNum;

                if(lJournalTable.Posted == NoYes::Yes)
                {
                    response.parmJournalNum(journalNum);
                    response.parmSuccess(true);
                    response.parmWorkflowStatus(enum2Str(lJournalTable.WorkflowApprovalStatus));
                }
                else
                {
                    response.parmJournalNum(journalNum);
                    response.parmSuccess(false);
                    response.parmWorkflowStatus(enum2Str(lJournalTable.WorkflowApprovalStatus));
                    response.parmErrorMessage(lJournalTable.METErrorLog);
                }
            }
            
        }
        catch (Exception::CLRError)
        {
            System.Exception interopException = CLRInterop::getLastException();

            response.parmJournalNum(journalNum);
            response.parmSuccess(false);
            response.parmWorkflowStatus(enum2Str(lJournalTable.WorkflowApprovalStatus));
            response.parmErrorMessage(lJournalTable.METErrorLog);
        }

        return response;
    }
